package com.gamehub.application.service; import com.gamehub.application.OperationsService; import java.util.List; public final class TournamentRegistrationService { private final OperationsService ops; public TournamentRegistrationService(OperationsService ops){this.ops=ops;} public List<String> tournaments()throws Exception{return ops.tournaments();} public List<String> registrations(long t)throws Exception{return ops.registrations(t);} public List<String> teams(long c)throws Exception{return ops.captainTeams(c);} public long solo(long t,long c)throws Exception{return ops.registerTournament(t,c);} public long team(long t,long c,long team)throws Exception{return ops.registerTournamentTeam(t,c,team);} }